import os
import json
from google.cloud import pubsub_v1

def consume_event(payload, config=None):
    config = config or {}
    subscriber = pubsub_v1.SubscriberClient()
    subscription_path = subscriber.subscription_path(
        os.getenv("GOOGLE_CLOUD_PROJECT", config.get("project_id", "your-project-id")),
        config.get("subscription_id", "your-subscription-id")
    )
    response = subscriber.pull(
        request={"subscription": subscription_path, "max_messages": 1}
    )
    if not response.received_messages:
        return None
    message = response.received_messages[0]
    result = json.loads(message.message.data.decode("utf-8"))
    subscriber.acknowledge(request={"subscription": subscription_path, "ack_ids": [message.ack_id]})
    return result
